CREATE     PROCEDURE [synapse_fo].[usp_Insert_GENERALJOURNALACCOUNTENTRY]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:49
	Description: Insert stored procedure for GENERALJOURNALACCOUNTENTRY from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[GENERALJOURNALACCOUNTENTRY]
	(
		[ACCOUNTINGCURRENCYAMOUNT],
		[ALLOCATIONLEVEL],
		[ASSETLEASEPOSTINGTYPES],
		[ASSETLEASETRANSACTIONTYPE],
		[CREATEDTRANSACTIONID],
		[DataLakeModified_DateTime],
		--[FileName],
		[FINTAG],
		[GENERALJOURNALENTRY],
		[HISTORICALEXCHANGERATEDATE],
		[ISCORRECTION],
		[ISCREDIT],
		[LastProcessedChange_DateTime],
		[LEDGERACCOUNT],
		[LEDGERDIMENSION],
		--[LSN],
		[MAINACCOUNT],
		[ORIGINALACCOUNTENTRY],
		[PARTITION],
		[PAYMENTREFERENCE],
		[POSTINGTYPE],
		[PROJID_SA],
		[PROJTABLEDATAAREAID],
		[QUANTITY],
		[REASONREF],
		[RECID],
		[RECVERSION],
		[REPORTINGCURRENCYAMOUNT],
		--[SysRowId],
		[TEXT],
		[TRANSACTIONCURRENCYAMOUNT],
		[TRANSACTIONCURRENCYCODE]
	)
	SELECT 
		stg.[ACCOUNTINGCURRENCYAMOUNT],
		stg.[ALLOCATIONLEVEL],
		stg.[ASSETLEASEPOSTINGTYPES],
		stg.[ASSETLEASETRANSACTIONTYPE],
		stg.[CREATEDTRANSACTIONID],
		stg.[DataLakeModified_DateTime],
		--stg.--[FileName],
		stg.[FINTAG],
		stg.[GENERALJOURNALENTRY],
		stg.[HISTORICALEXCHANGERATEDATE],
		stg.[ISCORRECTION],
		stg.[ISCREDIT],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGERACCOUNT],
		stg.[LEDGERDIMENSION],
		--stg.--[LSN],
		stg.[MAINACCOUNT],
		stg.[ORIGINALACCOUNTENTRY],
		stg.[PARTITION],
		stg.[PAYMENTREFERENCE],
		stg.[POSTINGTYPE],
		stg.[PROJID_SA],
		stg.[PROJTABLEDATAAREAID],
		stg.[QUANTITY],
		stg.[REASONREF],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REPORTINGCURRENCYAMOUNT],
		--stg.--[SysRowId],
		stg.[TEXT],
		stg.[TRANSACTIONCURRENCYAMOUNT],
		stg.[TRANSACTIONCURRENCYCODE]	
	FROM [staging_fo].[GENERALJOURNALACCOUNTENTRY] stg
		LEFT JOIN [synapse_fo].[GENERALJOURNALACCOUNTENTRY] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
